import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    p = 1
    names = []
    idx = {}
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    owner = {}
    for i in range(n):
        name = data[p]
        c = int(data[p + 1])
        names.append(name)
        idx[name] = i
        for k in range(c):
            t = data[p + 2 + k].lower()
            if t in owner:
                a, b = find(i), find(owner[t])
                if a != b:
                    parent[a] = b
            else:
                owner[t] = i
        p += 2 + c
    q = idx[data[p]]
    r = find(q)
    res = sorted(names[i] for i in range(n) if i != q and find(i) == r)
    print(' '.join(res) if res else -1)

